using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using Microsoft.Extensions.Logging;
using Xunit;
using Moq;

namespace Emby.Server.Implementations.Plugins.Tests
{
    public class PluginManagerTests
    {
        private class LocalPlugin
        {
            public string Id { get; set; } = "";
            public Version Version { get; set; } = new Version(1, 0, 0, 0);
            public bool IsEnabledAndSupported { get; set; } = true;
            public Manifest Manifest { get; set; } = new Manifest();
            public string Name { get; set; } = "TestPlugin";
        }

        private class Manifest
        {
            public PluginStatus Status { get; set; }
            public bool AutoUpdate { get; set; }
        }

        private enum PluginStatus
        {
            Active,
            Superseded,
            Restart,
            Deleted,
            Malfunctioned,
            NotSupported
        }

        private class TestPluginManager : Emby.Server.Implementations.Plugins.PluginManager
        {
            public TestPluginManager(ILogger<Emby.Server.Implementations.Plugins.PluginManager> logger)
                : base(logger, null!, null!, "", new Version(1, 0, 0, 0))
            {
                // We will override _plugins list via reflection
            }

            // Expose ProcessAlternative for testing via reflection or public method
            public void CallProcessAlternative(LocalPlugin plugin)
            {
                var method = typeof(Emby.Server.Implementations.Plugins.PluginManager)
                    .GetMethod("ProcessAlternative", BindingFlags.NonPublic | BindingFlags.Instance);
                method.Invoke(this, new object[] { plugin });
            }

            // We override ChangePluginState to simulate failure or success
            protected override bool ChangePluginState(LocalPlugin plugin, PluginStatus status)
            {
                // Simulate failure for previousVersion to trigger LogError
                return false;
            }

            // We override _plugins list via reflection
            public void SetPlugins(List<LocalPlugin> plugins)
            {
                var field = typeof(Emby.Server.Implementations.Plugins.PluginManager)
                    .GetField("_plugins", BindingFlags.NonPublic | BindingFlags.Instance);
                field.SetValue(this, plugins);
            }
        }

        [Fact]
        public void ProcessAlternative_LogsError_When_ChangePluginStateFails_ActiveStatus()
        {
            var loggerMock = new Mock<ILogger<Emby.Server.Implementations.Plugins.PluginManager>>();
            var manager = new TestPluginManager(loggerMock.Object);

            var previousVersion = new LocalPlugin
            {
                Id = "plugin1",
                Version = new Version(1, 0, 0, 0),
                IsEnabledAndSupported = true,
                Name = "PreviousPlugin",
                Manifest = new Manifest { Status = PluginStatus.Active }
            };

            var plugin = new LocalPlugin
            {
                Id = "plugin1",
                Version = new Version(2, 0, 0, 0),
                IsEnabledAndSupported = true,
                Name = "CurrentPlugin",
                Manifest = new Manifest { Status = PluginStatus.Active }
            };

            manager.SetPlugins(new List<LocalPlugin> { previousVersion, plugin });

            manager.CallProcessAlternative(plugin);

            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to enable version")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.Once);
        }

        [Fact]
        public void ProcessAlternative_LogsError_When_ChangePluginStateFails_SupersededStatus()
        {
            var loggerMock = new Mock<ILogger<Emby.Server.Implementations.Plugins.PluginManager>>();
            var manager = new TestPluginManager(loggerMock.Object);

            var previousVersion = new LocalPlugin
            {
                Id = "plugin1",
                Version = new Version(1, 0, 0, 0),
                IsEnabledAndSupported = true,
                Name = "PreviousPlugin",
                Manifest = new Manifest { Status = PluginStatus.Active }
            };

            var plugin = new LocalPlugin
            {
                Id = "plugin1",
                Version = new Version(2, 0, 0, 0),
                IsEnabledAndSupported = true,
                Name = "CurrentPlugin",
                Manifest = new Manifest { Status = PluginStatus.Superseded }
            };

            manager.SetPlugins(new List<LocalPlugin> { previousVersion, plugin });

            manager.CallProcessAlternative(plugin);

            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to supercede version")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.Once);
        }
    }
}
